#[derive(Debug, Clone, PartialEq)]
struct DType {
    kind: char, // 'b', 'i', 'u', 'f', 'c', 'O'
    precedence: u8,
}

impl DType {
    /// Creates a new DType with the given kind and precedence.
    /// 
    /// # Requires
    /// - `kind` must be a valid character representing the type.
    /// - `precedence` must be a non-negative value.
    ///
    /// # Ensures
    /// - The created DType has the specified kind and precedence.
    fn new(kind: char, precedence: u8) -> Self {
        DType { kind, precedence }
    }
}

fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Requires that types is not empty
    // Ensures that the returned DType has the maximum precedence
    assert!(!types.is_empty(), "types must not be empty");
    
    types.into_iter().max_by_key(|dtype| dtype.precedence).unwrap()
}

fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    // Requires that the function is called with valid vectors
    // Ensures that the returned Option<DType> is either Some(DType) or None
    // Invariant: If both arrays are empty, the function should return None
    assert!(array_types.is_empty() || !array_types.is_empty(), "array_types must be valid");
    assert!(scalar_types.is_empty() || !scalar_types.is_empty(), "scalar_types must be valid");

    let max_array = if !array_types.is_empty() {
        Some(find_max_precedence_type(array_types))
    } else {
        None
    };

    let max_scalar = if !scalar_types.is_empty() {
        Some(find_max_precedence_type(scalar_types))
    } else {
        None
    };

    match (max_array, max_scalar) {
        (Some(array_max), Some(scalar_max)) => {
            if array_max.kind == scalar_max.kind {
                Some(array_max)
            } else {
                Some(scalar_max)
            }
        }
        (Some(array_max), None) => Some(array_max),
        (None, Some(scalar_max)) => Some(scalar_max),
        (None, None) => None, // This case should not happen as per the problem statement
    }
}

fn main() {
    // Example usage
    let array_types = vec![
        DType::new('i', 3), // Int32
        DType::new('f', 9), // Float32
    ];
    
    let scalar_types = vec![
        DType::new('b', 0), // Bool
        DType::new('i', 1), // Int8
    ];

    let max_array_type = find_max_precedence_type(array_types.clone());
    println!("Max Array Type: {:?}", max_array_type);

    let common_type = find_common_type(array_types, scalar_types);
    println!("Common Type: {:?}", common_type);
}